    public static void initializeRetailSalesTable(RetailSalesTable _retailSalesTable, SalesTable _salesTable)
    {
        next initializeRetailSalesTable(_retailSalesTable, _salesTable);

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            _retailSalesTable.ShouldUseUnifiedPricingEngineOnSalesOrder = GUPParameters::find().EnableGlobalUnifiedPricingOnSalesOrder;
        }
    }
